head.script:
scwin.screenId = "jldbnf00400";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchBizFormListByCondReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $('#paging7 table:first-child').attr('align', 'center');
        $c.util.getComponent('paging7').firstChild.setAttribute('align', 'center');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf00400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_srchWord_onkeydown
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_srchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_srchWord_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(event.keyCode==13){replacePercent(selfVar);await scwin.searchBizFormListByCond();}
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00400.ipt_srchWord_onkeydown' }); }
};

/**
 * @event
 * @name scwin.ipt_srchWord_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_srchWord_onblur = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_srchWord_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        replacePercent(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.ipt_srchWord_onblur' }); }
};

/**
 * @event
 * @name scwin.btn_searchBizFormListByCond_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchBizFormListByCond_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchBizFormListByCond_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchBizFormListByCond()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00400.btn_searchBizFormListByCond_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.fileDown === 'function') { await scwin.fileDown(r["contnId"], r["attachFileNm"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDown (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDown'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.span_48_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.span_48_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin span_48_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.span_48_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchBizFormListByCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchBizFormListByCond = async function () {
    const sbmOptions = {
        id: "tx_fn_searchBizFormListByCond",
        method: "post",
        action: "/main/notice.do?method=searchNoticeList",
        ref: "dma_searchBizFormListByCondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf00400.tx_fn_searchBizFormListByCond" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_44").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchBizFormListByCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchBizFormListByCond = async function () {
    /* sdd-asis-lifecycle:begin fn_searchBizFormListByCond — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    let _previewWindow;
    _previewWindow = $c.win.openPopup("/notice/notice.xml", { id: "popBizFormList", resizable: false, type: "pageFramePopup" }, ($c.util.getComponent("dma_searchBizFormListByCondReq") ? $c.util.getComponent("dma_searchBizFormListByCondReq").getJSON() : {}));
    fm.action = '/main/notice.do?method=searchNoticeList';

    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_fileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (attachFileNm == null || attachFileNm === "") {
        await $c.win.alert("첨부파일이 없습니다.");
        return;
    }
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchBizFormListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_fileDown();
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_44_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_44_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchBizFormListByCondReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_44.page' }); } scwin.tx_fn_searchBizFormListByCond(); };
